import {rand, shuffle, format, isCorrect} from './questions.js';
// Fachliche Texte sind pro Themengebiet verfasst; kein generischer Ersatztext.
const lessonTexts = `
count|Zahlen beschreiben, wie viele Dinge zu einer Menge gehören. Beim Zählen bekommt jedes Ding genau ein Zahlwort. Auf dem Zahlenstrahl stehen kleine Zahlen links und größere rechts.|Der Nachfolger liegt einen Schritt rechts, der Vorgänger einen Schritt links. Vergleiche mehrstellige Zahlen von links: Zuerst zählt die höchste Stelle, erst bei Gleichstand die nächste.|Verwechsle die Zahl nicht mit einer einzelnen Ziffer. Die 2 in 20 hat einen anderen Wert als die 2 in 12.
place|Unser Zahlensystem bündelt immer zehn Einheiten zur nächstgrößeren Einheit. Zehn Einer sind ein Zehner, zehn Zehner ein Hunderter. Die Position einer Ziffer bestimmt ihren Wert.|Zerlege eine Zahl in Stellenwerte. Lies von rechts: Einer, Zehner, Hunderter, Tausender. Multipliziere jede Ziffer mit ihrem Stellenwert und addiere die Teilwerte wieder.|Eine Null hält eine Stelle frei. In 304 fehlen die Zehner; die 3 steht trotzdem für 300 und nicht für 30.
add|Addition fügt Mengen zusammen. Beide Summanden ergeben gemeinsam die Summe. Du kannst Zahlen in kleine, leichter rechenbare Teile zerlegen, ohne die Summe zu verändern.|Nutze einen passenden Zwischenschritt: erst bis zum nächsten Zehner, dann den Rest. Bei größeren Zahlen kannst du Hunderter, Zehner und Einer getrennt addieren und am Ende bündeln.|Ein Übertrag verschwindet nicht. Zehn Einer werden zu einem zusätzlichen Zehner. Prüfe durch Überschlagen, ob die Größenordnung passt.
subtract|Subtraktion beschreibt Wegnehmen oder einen Abstand. Von der Ausgangszahl wird eine Menge abgezogen. Anders als bei Plus darfst du die Zahlen nicht einfach vertauschen.|Zerlege die abzuziehende Zahl. Ziehe zuerst einen einfachen Teil und anschließend den Rest ab. Kontrolliere mit der Umkehrung: Ergebnis plus abgezogene Zahl ergibt die Ausgangszahl.|Wenn du einen Zehner in zehn Einer tauschst, muss die Zehnerstelle um eins kleiner werden. Beachte beim Rechnen über den Zehner beide Schritte.
missing|Ein Kästchen steht für eine unbekannte Zahl. Gesucht ist keine Schätzung, sondern die Zahl, mit der die gesamte Rechnung stimmt.|Nutze die Umkehraufgabe. Bei einer fehlenden Zahl in einer Addition ziehst du den bekannten Summanden von der Summe ab. Setze das Ergebnis anschließend in die ursprüngliche Aufgabe ein.|Das Gleichheitszeichen bedeutet: Beide Seiten haben denselben Wert. Es ist keine Aufforderung, nur die Zahlen links auszurechnen.
sequence|Eine Zahlenfolge ist eine geordnete Reihe von Zahlen. Viele einfache Muster verändern sich jedes Mal um denselben Betrag. Das heißt konstante Schrittweite.|Vergleiche mehrere benachbarte Zahlen. Ermittle ihre Differenz und prüfe die Vermutung an einem zweiten Paar. Führe dieselbe Veränderung bei der letzten Zahl fort.|Eine einzelne Differenz beweist noch keine Regel. Manche Folgen wechseln zwischen zwei Regeln; hier üben wir gleichmäßige Folgen mit konstanter Schrittweite.
shapes|Geometrische Formen erkennst du an ihren Eigenschaften, nicht an ihrer Farbe oder Ausrichtung. Eine Ecke ist die Stelle, an der zwei Seiten zusammentreffen.|Zähle Seiten und Ecken. Beim Quadrat sind alle vier Seiten gleich lang und alle Winkel recht. Ein Rechteck hat vier rechte Winkel; ein Kreis hat keine Ecken.|Ein gedrehtes Quadrat bleibt ein Quadrat. Außerdem ist jedes Quadrat ein besonderes Rechteck, aber nicht jedes Rechteck ein Quadrat.
story|Sachaufgaben übersetzen eine Alltagssituation in Mathematik. Die entscheidende Frage ist: Was wird gesucht und welche Angaben helfen dabei?|Markiere die wichtigen Angaben, plane die Rechnung und rechne Schritt für Schritt. Schreibe am Ende einen Antwortsatz mit Einheit. Eine Probe zeigt, ob deine Antwort zur Geschichte passt.|Nicht jede Zahl im Text muss benutzt werden. Achte darauf, ob nach einer einzelnen Person oder nach der gesamten Gruppe gefragt wird.
numberLine|Der Zahlenstrahl ordnet Zahlen und macht Abstände sichtbar. Gleich lange Strecken stehen für gleich große Zahlenunterschiede.|Suche die kleinere und die größere Zahl. Zähle die Schritte dazwischen oder rechne größere Zahl minus kleinere Zahl. Jeder Abschnitt muss dieselbe Skalierung haben.|Zähle die Zwischenräume, nicht die Striche. Zwischen 2 und 5 liegen drei Schritte, obwohl du vier beschriftete Zahlen sehen kannst.
multiply|Multiplikation fasst gleich große Gruppen zusammen. Drei Gruppen mit je vier Gegenständen sind 3 · 4. Die Reihenfolge der Faktoren ändert das Ergebnis nicht.|Für größere Zahlen zerlegst du einen Faktor: 14 · 6 = 10 · 6 + 4 · 6. Berechne die beiden Teilprodukte und addiere sie. So wird aus einer schweren Aufgabe eine Kombination einfacher Aufgaben.|Verwechsle Malrechnen nicht mit Addieren: 3 · 4 ist 12, während 3 + 4 nur 7 ist. Bei Teilprodukten dürfen keine Stellen verloren gehen.
divide|Division verteilt eine Menge auf gleich große Gruppen oder fragt, wie viele Gruppen hineinpassen. Sie ist die Umkehrung der Multiplikation.|Suche ein passendes Vielfaches des Divisors. Bei einer Aufgabe mit Rest ziehst du das größte passende Vielfache ab. Prüfe: Quotient · Divisor + Rest ergibt den Dividend.|Der Rest muss kleiner als der Divisor sein. Durch null darfst du nicht teilen. Hier geben wir Quotient und Rest getrennt ein.
money|Euro und Cent sind zwei Einheiten für denselben Geldwert. Ein Euro entspricht 100 Cent. Mit einer gemeinsamen Einheit lassen sich Beträge sicher vergleichen.|Wandle die Beträge zuerst in Cent um. Berechne die Differenz zwischen bezahltem Betrag und Preis. Teile danach durch 100, um das Rückgeld in Euro auszudrücken.|2,05 € sind 205 Cent und nicht 250 Cent. Das Komma trennt Euro von Hundertsteln eines Euro; fehlende Stellen werden mit null ergänzt.
clock|Eine analoge Uhr hat einen kurzen Stundenzeiger und einen längeren Minutenzeiger. Ein kompletter Umlauf des Minutenzeigers sind 60 Minuten, ein Abstand zwischen zwei Zahlen sind 5 Minuten.|Lies zuerst die Stunde ab und danach die Minuten. Für die Minuten multiplizierst du die Zahl am langen Zeiger mit 5. Bei der 12 sind es 0 Minuten der neuen Stunde.|Der Stundenzeiger wandert während der Stunde weiter. Halb acht bedeutet 7:30 Uhr und nicht 8:30 Uhr.
time|Stunden und Minuten bilden kein Zehnersystem. Eine Stunde hat 60 Minuten, ein Tag 24 Stunden. Für Rechnungen brauchst du dieselbe Einheit.|Multipliziere ganze Stunden mit 60 und addiere zusätzliche Minuten. Bei Zeitspannen über eine volle Stunde kannst du erst bis zur vollen Stunde und dann weiterrechnen.|1,5 Stunden sind 90 Minuten, nicht 150. Eine Dezimalzahl und eine Schreibweise mit Stunden und Minuten bedeuten nicht dasselbe.
units|Eine Größe besteht aus Zahlenwert und Einheit. Dieselbe Länge kann zum Beispiel als Meter oder Zentimeter angegeben werden. Der Gegenstand wird beim Umrechnen nicht größer.|Bestimme zuerst den Umrechnungsfaktor. Von Metern zu Zentimetern multiplizierst du mit 100; in der Gegenrichtung teilst du durch 100. Notiere die Zieleinheit bei jedem Ergebnis.|Flächen und Volumen haben andere Faktoren: Ein Quadratmeter sind 10.000 Quadratzentimeter. Hier beginnen wir mit Längen und einfachen Einheiten.
perimeter|Der Umfang ist die Länge des Randes einer Figur. Stell dir vor, du legst ein Band einmal außen herum. Beim Rechteck sind jeweils zwei gegenüberliegende Seiten gleich lang.|Addiere alle vier Seiten oder nutze U = 2 · (a + b). Rechne erst die Summe zweier benachbarter Seiten aus und verdopple sie. Das Ergebnis hat eine Längeneinheit.|Umfang und Fläche sind verschieden. Für einen Zaun brauchst du Meter, für den Bodenbelag Quadratmeter.
calendar|Kalender ordnen Tage in Wochen und Monate. Eine Woche besteht immer aus sieben Tagen, während Monate unterschiedlich lang sind.|Für Wochentage zerlegst du eine Zeitspanne in volle Wochen und übrige Tage. Volle Wochen verändern den Wochentag nicht. Gehe nur den Rest der Tage weiter.|Ein Monat ist nicht immer vier Wochen lang. Schaltjahre und Monatslängen sind bei Datumsrechnungen zu beachten; die Übungen hier fragen nach Wochentagen.
round|Runden ersetzt eine Zahl durch eine nahe, leichter überschaubare Zahl. Wie genau du rundest, hängt von der gewählten Stelle ab.|Suche die beiden benachbarten Vielfachen der Rundungsstelle. Entscheide über die nächste kleinere Stelle: 0 bis 4 abrunden, 5 bis 9 aufrunden. Rechts davon stehen anschließend Nullen.|Erst die Rundungsstelle festlegen: Auf Zehner und auf Hunderter gerundet kann dieselbe Zahl unterschiedliche Ergebnisse liefern.
fraction|Ein Bruch beschreibt gleich große Teile eines Ganzen. Der Nenner nennt die Anzahl aller Teile, der Zähler zählt die ausgewählten Teile.|Um einen Anteil zu berechnen, teilst du das Ganze durch den Nenner und multiplizierst mit dem Zähler. Beim Kürzen teilst du Zähler und Nenner durch dieselbe Zahl.|Die Teile müssen gleich groß sein. Ein größerer Nenner bedeutet bei gleichem Zähler kleinere Teile, nicht einen größeren Anteil.
area|Die Fläche misst, wie viele Einheitsquadrate eine Figur bedecken. In einem Rechteck bilden diese Quadrate gleich lange Reihen und Spalten.|Multipliziere Länge und Breite: A = a · b. Beide Längen müssen dieselbe Einheit haben. Zerlege zusammengesetzte Flächen in bekannte Teilflächen, die sich nicht überlappen.|Die Einheit wird quadriert: cm · cm = cm². Verwechsle die Fläche nicht mit der Summe der Seitenlängen.
probability|Eine Wahrscheinlichkeit beschreibt, wie häufig ein Ereignis bei sehr vielen Wiederholungen ungefähr zu erwarten ist. Sie liegt zwischen 0 und 1.|Bei einem fairen Würfel sind alle sechs Ergebnisse gleich wahrscheinlich. Zähle die günstigen Ergebnisse und teile durch die Anzahl aller möglichen Ergebnisse.|Die Laplace-Regel gilt nur bei gleich wahrscheinlichen Ergebnissen. Eine Wahrscheinlichkeit von 1/2 garantiert nicht, dass bei zwei Versuchen genau ein Treffer kommt.
data|Daten lassen sich in Tabellen und Diagrammen darstellen. Eine Balkenhöhe kann beispielsweise die Anzahl abgegebener Stimmen oder erzeugte Energiemengen zeigen.|Lies zuerst Beschriftung und Einheit. Ermittle einzelne Werte und führe die zur Frage passende Rechnung aus: Summe, Differenz oder Vergleich. Bei Summen müssen die Kategorien zusammenpassen.|Eine hohe Säule allein reicht nicht: Die Skalierung der Achse bestimmt ihren Wert. Vergleiche keine Balken aus unterschiedlich skalierten Diagrammen ohne Umrechnung.
solids|Ein Körper hat räumliche Ausdehnung. Flächen begrenzen ihn, Kanten sind die Übergänge zwischen Flächen und an Ecken treffen Kanten zusammen.|Beim Würfel zählen wir 6 quadratische Flächen, 12 Kanten und 8 Ecken. Ein Würfelnetz zeigt die sechs Flächen aufgeklappt in einer Ebene.|Ein Netz ist nicht schon deshalb ein Würfelnetz, weil es sechs Quadrate enthält. Die Quadrate müssen sich ohne Überlappung zum Würfel falten lassen.
operations|Rechenregeln sorgen dafür, dass ein Term eindeutig ausgewertet wird. Klammern legen eine Reihenfolge fest, auch wenn sie von Punkt vor Strich abweicht.|Rechne zuerst Klammern, anschließend Multiplikation und Division, zuletzt Addition und Subtraktion. Gleichrangige Operationen rechnest du von links nach rechts.|Nicht einfach immer links anfangen: In 4 + 3 · 2 wird zuerst 3 · 2 berechnet. Klammern können das Ergebnis ändern.
divisibility|Eine Zahl ist durch eine andere teilbar, wenn beim Teilen kein Rest bleibt. Teilbarkeitsregeln nutzen die Ziffern einer Zahl, um diese Eigenschaft schnell zu prüfen.|Durch 2: letzte Ziffer gerade. Durch 5: letzte Ziffer 0 oder 5. Durch 3 oder 9: Prüfe die Quersumme. Zur Kontrolle kannst du Quotient und Rest berechnen.|Eine durch 3 teilbare Quersumme macht die Zahl nicht automatisch durch 9 teilbar. Achte genau auf die Regel des gesuchten Teilers.
prime|Eine Primzahl ist eine natürliche Zahl größer als 1 mit genau zwei positiven Teilern. Sie lässt sich nur durch 1 und sich selbst ohne Rest teilen.|Prüfe mögliche Teiler. Für einen Nachweis genügt es, die Primteiler bis zur Quadratwurzel der Zahl zu untersuchen. Findest du einen echten Teiler, ist die Zahl zusammengesetzt.|1 ist keine Primzahl. 2 ist die einzige gerade Primzahl, denn alle größeren geraden Zahlen haben zusätzlich den Teiler 2.
volume|Das Volumen misst den Rauminhalt eines Körpers in Einheitswürfeln. Ein Quader besteht aus rechteckigen Schichten gleicher Größe.|Berechne zuerst die Grundfläche a · b. Multipliziere diese Fläche mit der Höhe c. So erhältst du V = a · b · c und eine kubische Einheit.|Volumen und Oberfläche sind verschieden. Einheiten wie cm³ bezeichnen Rauminhalt, cm² dagegen eine Fläche.
symmetry|Bei einer Spiegelung haben Original und Bild denselben Abstand zur Spiegelachse. Im Koordinatensystem lässt sich das an Vorzeichen erkennen.|An der y-Achse ändert die x-Koordinate ihr Vorzeichen, y bleibt gleich. An der x-Achse bleibt x gleich, y wechselt das Vorzeichen. Zeichne die Achse zur Kontrolle ein.|Spiegeln ist nicht dasselbe wie x und y vertauschen. Die Koordinate entlang der Spiegelachse bleibt unverändert.
angles|Ein Winkel beschreibt die Öffnung zwischen zwei Strahlen. Wir messen ihn in Grad. Eine Vierteldrehung entspricht 90°, eine halbe Drehung 180°.|Vergleiche die Winkelgröße mit 90° und 180°. Unter 90° ist der Winkel spitz, genau 90° recht, zwischen 90° und 180° stumpf.|Die Länge der gezeichneten Schenkel verändert den Winkel nicht. Entscheidend ist die Öffnung, nicht die Größe der Zeichnung.
gcd|Der größte gemeinsame Teiler teilt zwei Zahlen ohne Rest. Das kleinste gemeinsame Vielfache ist die kleinste positive Zahl, die ein Vielfaches beider Zahlen ist.|Du kannst Teilerlisten vergleichen. Sind ggT und beide Zahlen bekannt, gilt für positive ganze Zahlen: kgV = a · b / ggT. Das hilft auch bei gemeinsamen Nennern.|ggT und kgV dürfen nicht verwechselt werden: Der ggT ist höchstens so groß wie die kleinere Zahl, das kgV mindestens so groß wie die größere.
negative|Negative Zahlen beschreiben Werte unter null, zum Beispiel Temperaturen oder Kontostände. Auf dem Zahlenstrahl liegen sie links von null.|Beim Addieren einer positiven Zahl gehst du nach rechts, beim Addieren einer negativen nach links. Zerlege einen Weg über null in zwei Abschnitte.|Ein Minuszeichen kann ein Vorzeichen oder eine Rechenoperation sein. Die Klammer in −5 + (−3) macht deutlich, dass eine negative Zahl addiert wird.
fractions|Brüche können nur direkt addiert werden, wenn ihre Teile gleich groß sind. Der gemeinsame Nenner stellt genau diese gleiche Teilgröße her.|Erweitere beide Brüche auf einen gemeinsamen Nenner. Addiere dann die Zähler und behalte den Nenner. Kürze am Ende, falls ein gemeinsamer Teiler vorhanden ist.|Addiere niemals einfach die Nenner. 1/2 + 1/2 ist 1 und nicht 2/4. Gleichwertige Brüche beschreiben denselben Wert.
fractionProduct|Beim Multiplizieren von Brüchen berechnest du einen Anteil eines Anteils. Beim Dividieren fragst du, wie oft ein Bruch in einen anderen passt.|Multipliziere Zähler mit Zähler und Nenner mit Nenner. Für eine Division drehst du nur den zweiten Bruch um und multiplizierst mit diesem Kehrwert.|Der Kehrwert von 2/3 ist 3/2. Ein Bruch mit Wert null hat keinen Kehrwert. Kürzen ist auch vor der Multiplikation möglich.
decimal|Dezimalzahlen schreiben Bruchteile im Zehnersystem. Rechts vom Komma stehen Zehntel, Hundertstel und Tausendstel. 0,25 sind 25 Hundertstel.|Bringe Zahlen gedanklich auf dieselbe Nachkommastellenzahl. Addiere gleichwertige Stellen. Eine Rechnung mit Hundertsteln kann zunächst wie eine Ganzzahlrechnung behandelt werden.|Kommas müssen beim Addieren untereinander stehen. Eine angehängte Null verändert den Wert nicht: 0,5 = 0,50.
percent|Prozent bedeutet von hundert. Der Grundwert ist das Ganze, der Prozentsatz beschreibt den Anteil und der Prozentwert ist die dazugehörige Menge.|Berechne zuerst 1 % durch Teilen durch 100. Multipliziere anschließend mit dem Prozentsatz. Bei einem Rabatt ziehst du den Prozentwert vom ursprünglichen Preis ab.|Prüfe immer, auf welches Ganze sich die Prozentangabe bezieht. Nach einer Preiserhöhung bezieht sich ein späterer Rabatt oft auf den neuen Preis.
proportion|Bei einer proportionalen Zuordnung wachsen zwei Größen im gleichen Verhältnis. Doppelte Menge bedeutet doppelten Gesamtpreis, sofern der Einzelpreis konstant bleibt.|Nutze den Dreisatz: von der bekannten Menge auf eine Einheit teilen, danach auf die gesuchte Menge multiplizieren. Der Quotient Gesamtpreis durch Menge bleibt gleich.|Ein fester Grundpreis oder Mengenrabatt kann die Proportionalität aufheben. Prüfe die Annahme, bevor du den Dreisatz anwendest.
inverse|Bei einer antiproportionalen Zuordnung wird eine Größe kleiner, wenn die andere im gleichen Verhältnis größer wird. Das Produkt beider Größen bleibt konstant.|Berechne zuerst die gesamte Arbeitsmenge als Personen mal Zeit. Teile sie dann durch die neue Personenzahl. Das setzt gleich schnelle Personen und teilbare Arbeit voraus.|Mehr Personen bedeuten nicht bei jeder Tätigkeit entsprechend weniger Zeit. Eine Arbeit muss tatsächlich parallel ausführbar sein.
circle|Beim Kreis sind alle Randpunkte gleich weit vom Mittelpunkt entfernt. Dieser Abstand ist der Radius r. Der Durchmesser d ist doppelt so groß.|Für den Umfang gilt U = 2πr oder πd. Berechne zuerst den Durchmesser und multipliziere mit π. In unseren Rechenaufgaben steht jeweils, welche Näherung du verwenden sollst.|Radius und Durchmesser dürfen nicht verwechselt werden. Ein gerundeter Wert für π liefert nur einen Näherungswert des Umfangs.
mean|Statistische Kennwerte fassen Daten auf unterschiedliche Weise zusammen. Der Mittelwert verteilt die Gesamtsumme gleichmäßig, der Median liegt in der sortierten Mitte.|Für den Mittelwert addierst du alle Werte und teilst durch ihre Anzahl. Für den Median sortierst du zuerst. Die Spannweite ist größter minus kleinster Wert.|Ein einzelner sehr großer Wert kann den Mittelwert stark verändern. Der Median ist dagegen gegenüber einzelnen Ausreißern oft weniger empfindlich.
triangleArea|Die Fläche eines Dreiecks ist halb so groß wie die eines passenden Parallelogramms mit gleicher Grundseite und Höhe. Die Höhe ist ein senkrechter Abstand.|Multipliziere Grundseite und zugehörige Höhe. Beim Dreieck teilst du das Produkt durch 2; beim Parallelogramm bleibt das Produkt unverändert.|Eine schräge Seitenlänge ist meistens nicht die Höhe. Die Höhe muss senkrecht auf der gewählten Grundseite stehen.
terms|Eine Variable steht für eine Zahl. Gleichartige Terme haben denselben Variablenteil und dürfen über ihre Zahlenfaktoren zusammengefasst werden.|Fasse x-Terme mit x-Termen zusammen und behandle konstante Zahlen getrennt. Beispielsweise werden 3x + 4x zu 7x; eine zusätzliche 2 bleibt als eigener Summand erhalten.|x und x² sind nicht gleichartig. Aus 3x + 2 wird nicht 5x, weil die 2 keinen Faktor x besitzt.
equation|Eine Gleichung fordert gleiche Werte auf beiden Seiten. Du suchst die Zahl für x, die diese Gleichheit erfüllt. Jede erlaubte Umformung muss auf beiden Seiten geschehen.|Entferne zuerst eine addierte oder subtrahierte Zahl mit der Umkehroperation. Teile danach beide Seiten durch den Faktor vor x. Prüfe durch Einsetzen.|Teile immer die gesamte Seite. Durch eine Zahl zu teilen, die null sein könnte, ist ohne Fallunterscheidung nicht erlaubt.
distribute|Das Distributivgesetz verteilt einen Faktor vor einer Klammer auf jeden Summanden darin. Es verbindet Multiplikation und Addition.|Multipliziere den äußeren Faktor mit dem ersten und mit jedem weiteren Klammerterm. Schreibe alle Teilprodukte mit ihrem Vorzeichen auf und fasse danach zusammen.|Ein Minus vor der Klammer wirkt auf jeden Summanden. Bei −(x + 3) wird auch die 3 negativ. Du kannst das Minus als Multiplikation der ganzen Klammer mit −1 verstehen.
linear|Eine lineare Funktion ordnet jedem x einen Wert y = mx + b zu. Der Graph ist eine Gerade. m beschreibt die Steigung, b den Schnitt mit der y-Achse.|Setze den gewünschten x-Wert in den Term ein. Multipliziere zuerst mit m und addiere dann b. Zum Zeichnen kannst du mehrere so berechnete Punkte eintragen.|Ein negatives m bedeutet eine fallende Gerade. Der Achsenabschnitt b ist ein y-Wert und nicht die Nullstelle der Funktion.
triangle|Die drei Innenwinkel eines ebenen Dreiecks ergeben zusammen 180°. Kennst du zwei Winkel, ist der dritte dadurch festgelegt.|Addiere die beiden bekannten Winkel. Ziehe diese Summe von 180° ab. Kontrolliere, ob alle drei Winkel positiv sind und ihre Summe wirklich 180° beträgt.|Die Regel gilt für Innenwinkel. Ein anliegender Außenwinkel gehört nicht einfach mit in dieselbe Summe.
congruence|Kongruente Dreiecke sind deckungsgleich, eventuell nach Verschieben, Drehen oder Spiegeln. Bestimmte Seiten- und Winkelangaben legen ihre Form und Größe fest.|SSS, SWS und WSW sind wichtige Kongruenzsätze. Beim Satz des Thales liegt ein Eckpunkt auf dem Halbkreis über der gegenüberliegenden Seite; der Winkel dort ist recht.|Drei Winkel legen nur die Form fest, nicht die Größe. Beim Thalessatz muss die betreffende Seite tatsächlich der Durchmesser des Halbkreises sein.
inequality|Eine Ungleichung beschreibt einen Bereich möglicher Zahlen. Das Zeichen < bedeutet kleiner als und > größer als; die Grenze selbst gehört bei diesen Zeichen nicht dazu.|Forme ähnlich wie bei einer Gleichung um. Beim Teilen oder Multiplizieren mit einer negativen Zahl drehst du das Zeichen um. Notiere danach Zeichen und Grenze zusammen.|Das Umdrehen gilt beim Multiplizieren oder Dividieren mit einer negativen Zahl, nicht beim bloßen Addieren einer negativen Zahl.
construction|Eine geometrische Konstruktion nutzt vorgegebene Eigenschaften statt bloßes Augenmaß. Zirkel und Lineal helfen, gleiche Abstände und genaue Schnittpunkte zu finden.|Die Mittelsenkrechte geht durch den Mittelpunkt einer Strecke und steht senkrecht auf ihr. Zwei gleich große Kreise um die Endpunkte liefern passende Punkte für ihre Konstruktion.|Eine Skizze erklärt die Idee, ersetzt aber keine genaue Konstruktion. Hier trainierst du die nötigen Eigenschaften; ein virtuelles Zirkelwerkzeug ist nicht enthalten.
systems|Ein lineares Gleichungssystem fordert, dass dieselben Werte für x und y beide Gleichungen erfüllen. Jede einzelne Gleichung reicht dazu im Allgemeinen nicht aus.|Wähle das Additionsverfahren, wenn sich eine Variable beim Addieren aufhebt. Bestimme die andere Variable, setze sie in eine ursprüngliche Gleichung ein und prüfe beide.|Ein gefundenes Zahlenpaar muss beide Gleichungen erfüllen. Manche Systeme haben keine oder unendlich viele Lösungen; die Übungen hier haben eine eindeutige Lösung.
pythagoras|In einem rechtwinkligen Dreieck ist die Hypotenuse die Seite gegenüber dem rechten Winkel. Die Quadrate der Katheten ergeben zusammen ihr Quadrat.|Berechne a² und b², addiere beide Werte und ziehe die nichtnegative Quadratwurzel: c = √(a² + b²). Soll eine Kathete gefunden werden, musst du entsprechend subtrahieren.|Der Satz gilt nur im rechtwinkligen Dreieck. Die längste Seite ist die Hypotenuse; sie darf nicht mit einer Kathete vertauscht werden.
roots|Die Quadratwurzel √a ist die nichtnegative Zahl, deren Quadrat a ergibt. Wurzelziehen kehrt das Quadrieren auf den nichtnegativen Zahlen um.|Nutze bekannte Quadratzahlen. Weil 12² = 144 gilt, ist √144 = 12. Liegt keine Quadratzahl vor, kannst du die Wurzel zwischen benachbarten Quadratzahlen einschätzen.|√9 ist 3 und nicht ±3. Die Gleichung x² = 9 hat dagegen zwei Lösungen, nämlich 3 und −3. Unterscheide daher die einzelne Wurzel von der Lösungsmenge einer Gleichung.
rational|Bei einer rationalen Funktion steht eine Variable in einem Bruchterm. In f(x) = a/x hängt der Funktionswert umgekehrt proportional von x ab.|Prüfe zuerst, ob der eingesetzte x-Wert erlaubt ist. Bei a/x muss x ungleich null sein. Setze danach ein und führe die Division aus.|Durch null darfst du nicht teilen. Eine Lücke im Definitionsbereich verschwindet nicht dadurch, dass man einen Graphen zeichnet.
interest|Zinsen sind ein prozentualer Zuwachs auf Kapital. Werden sie mit angelegt, wächst die Grundlage für die Zinsen des nächsten Jahres: Das ist Zinseszins.|Für ein Jahr berechnest du Z = K · p/100. Addiere die Zinsen zum Kapital und verwende für das nächste Jahr dieses neue Kapital. Allgemein gilt Kₙ = K₀ · (1 + p/100)ⁿ.|Zinseszins ist nicht gleich mehrfach dieselben Anfangszinsen addieren. Runde erst am Ende auf Cent, wenn nichts anderes vereinbart ist.
compound|Ein mehrstufiges Zufallsexperiment besteht aus aufeinanderfolgenden Versuchen. Ein Pfad beschreibt eine konkrete Folge von Ergebnissen.|Multipliziere die Wahrscheinlichkeiten entlang eines Pfades. Wenn mehrere Pfade zum gesuchten Ereignis gehören, addierst du ihre Wahrscheinlichkeiten. Mit Zurücklegen bleibt die Verteilung unverändert.|Ohne Zurücklegen verändern sich die Anzahlen und damit die Wahrscheinlichkeiten. Unabhängigkeit darf nicht einfach vorausgesetzt werden.
binomialFormula|Binomische Formeln sparen beim Ausmultiplizieren von zwei gleichen oder gegensätzlich aufgebauten Klammern Arbeit. Sie folgen aus dem Distributivgesetz.|Bei (x + b)² multiplizierst du (x + b)(x + b). Es entstehen x², zweimal bx und b². Zusammen ergibt das x² + 2bx + b².|Der Mittelterm 2bx darf nicht fehlen. Das Quadrat einer Summe ist nicht bloß die Summe der Quadrate.
surface|Die Oberfläche ist die Summe aller äußeren Flächen eines Körpers. Beim Quader gibt es drei Paare gleich großer Rechtecke.|Berechne die drei unterschiedlichen Flächen ab, ac und bc. Addiere sie und verdopple die Summe: O = 2(ab + ac + bc).|Für die Oberfläche verwendest du quadratische Einheiten. Das Produkt abc ist dagegen das Volumen und beschreibt etwas anderes.
slope|Die Steigung einer Geraden beschreibt die Änderung von y pro Änderung von x. Sie kann positiv, null oder negativ sein.|Berechne Δy = y₂ − y₁ und Δx = x₂ − x₁. Teile anschließend Δy durch Δx. Verwende für beide Differenzen dieselbe Reihenfolge der Punkte.|Bei Δx = 0 ist die Gerade senkrecht und hat keine endliche Steigung. Vertausche nicht nur in einer der beiden Differenzen die Reihenfolge.
quadratic|Eine quadratische Gleichung enthält x² als höchste Potenz. Sie kann zwei, eine oder keine reellen Lösungen besitzen. Nullstellen sind die x-Werte mit Funktionswert null.|Bringe die Gleichung in Normalform. Nutze Faktorisieren oder die p-q-Formel. In unseren Faktorbeispielen untersuchst du beide Klammern getrennt und prüfst die zwei Lösungen.|Aus einem Produkt gleich null folgt: Mindestens ein Faktor ist null. Aus einer Summe gleich null folgt diese Regel nicht.
powers|Eine Potenz beschreibt wiederholte Multiplikation derselben Basis. Der Exponent zählt die Faktoren. Potenzgesetze machen Produkte mit gleicher Basis übersichtlich.|Beim Multiplizieren gleicher Basen addierst du die Exponenten. Beim Potenzieren einer Potenz multiplizierst du die Exponenten. Die Basis bleibt bei diesen Regeln erhalten.|a³ + a² ist im Allgemeinen nicht a⁵. Die Additionsregel der Exponenten gilt für das Produkt gleicher Basen.
rootRules|Wurzelgesetze erlauben es, nichtnegative Faktoren unter einer Wurzel aufzuteilen. Ein quadratischer Faktor lässt sich dadurch aus der Wurzel ziehen.|Suche im Radikanden einen möglichst großen Quadratzahlfaktor. Zerlege zum Beispiel 72 in 36 · 2. Dann ist √72 = √36 · √2 = 6√2.|Für Summen gibt es diese Regel nicht: √(a + b) ist im Allgemeinen nicht √a + √b. Im Reellen gelten hier nichtnegative Radikanden.
trig|Sinus, Kosinus und Tangens beschreiben Seitenverhältnisse im rechtwinkligen Dreieck. Gegen- und Ankathete beziehen sich immer auf den gewählten Winkel.|Bestimme zuerst den Winkel und benenne die Seiten relativ dazu. Sinus verwendet Gegenkathete/Hypotenuse, Kosinus Ankathete/Hypotenuse, Tangens Gegenkathete/Ankathete.|Wechselt der Bezugswinkel, tauschen Gegen- und Ankathete ihre Rollen. Die Hypotenuse bleibt die Seite gegenüber dem rechten Winkel.
intercept|Ähnliche Dreiecke haben dieselben Winkel und entsprechende Seiten im gleichen Verhältnis. Der Vergrößerungsfaktor ist für alle passenden Seiten gleich.|Bestimme den Maßstabsfaktor mit einem bekannten Seitenpaar. Multipliziere eine andere Ausgangsseite mit demselben Faktor, um ihre entsprechende Bildseite zu finden.|Ordne immer entsprechende Seiten zu. Ein Verhältnis aus nicht zusammengehörigen Seiten liefert keinen brauchbaren Maßstabsfaktor.
parabola|Eine quadratische Funktion hat einen parabelförmigen Graphen. In der Scheitelpunktform a(x − d)² + e kannst du den Scheitel direkt erkennen.|Der Scheitel liegt bei S(d, e). Bei x = d wird der quadratische Term null. Das Vorzeichen von a entscheidet über die Öffnungsrichtung.|Das Vorzeichen in der Klammer ist umgekehrt zu lesen: (x + 3)² hat d = −3. Der äußere Summand e wird ohne Vorzeichenwechsel übernommen.
cylinder|Zylinder und Kegel haben eine kreisförmige Grundfläche. Bei gleichem Radius und gleicher Höhe hat der Kegel ein Drittel des Zylindervolumens.|Berechne die Kreisgrundfläche πr² und multipliziere mit der Höhe. Für den Kegel teilst du danach durch 3. Verwende den angegebenen Näherungswert für π.|Die Höhe ist der senkrechte Abstand zur Grundfläche und beim Kegel nicht die schräge Mantellinie. Das Volumen hat eine kubische Einheit.
conditional|Eine bedingte Wahrscheinlichkeit verwendet eine eingeschränkte Bezugsmenge. P(A gegeben B) fragt nur innerhalb der Fälle, in denen B bereits eingetreten ist.|Zähle, wie viele Fälle beide Eigenschaften haben. Teile diese Anzahl durch die Anzahl der Fälle mit der Bedingung B. Bei Vierfeldertafeln hilft das Markieren der passenden Zeile oder Spalte.|P(A gegeben B) ist nicht automatisch P(B gegeben A). Die Bezugsmenge im Nenner muss zur genannten Bedingung gehören.
factor|Faktorisieren schreibt eine Summe als Produkt. Gemeinsame Faktoren werden ausgeklammert. Das ist die Umkehrung des Ausmultiplizierens.|Finde einen gemeinsamen Zahlen- und Variablenfaktor. Teile jeden Summanden durch diesen Faktor und schreibe die verbleibenden Teile in die Klammer. Prüfe durch Ausmultiplizieren.|Jeder Summand muss durch den ausgeklammerten Faktor geteilt werden. Auch ein verbleibender Faktor 1 muss innerhalb der Klammer berücksichtigt werden.
polynomial|Polynome sind Summen aus Potenzen von x mit nichtnegativen ganzzahligen Exponenten. In einer Produktdarstellung lassen sich Nullstellen oft direkt ablesen.|Setze jeden linearen Faktor einzeln gleich null. Löse die entstehenden einfachen Gleichungen und sammle alle Nullstellen. Ein Faktor x liefert dabei die Nullstelle 0.|Eine Nullstelle ist ein x-Wert, nicht der y-Achsenabschnitt. Ein mehrfach auftretender Faktor kann dieselbe Nullstelle mehrfach enthalten.
exponential|Exponentielles Wachstum verändert einen Bestand in jedem Schritt um denselben Faktor. Der absolute Zuwachs wird dadurch im Allgemeinen größer.|Wandle den Prozentsatz in den Wachstumsfaktor q = 1 + p/100 um. Multipliziere den Startwert für jeden Schritt mit q. Nach t Schritten gilt a · qᵗ.|Gleiche prozentuale Zuwächse sind keine gleichen absoluten Zuwächse. Bei Abnahme lautet der Faktor 1 − p/100.
log|Ein Logarithmus fragt nach einem Exponenten. log_b(a) = x bedeutet: Welche Potenz von b ergibt a? Er ist die Umkehrung des Potenzierens.|Schreibe die gesuchte Beziehung als bˣ = a. Erkenne passende Potenzen oder verwende einen Taschenrechner. Kontrolliere das Ergebnis durch erneutes Potenzieren.|Im Reellen muss das Argument positiv sein. Die Basis muss positiv und ungleich 1 sein. Ein Logarithmus ist keine Division durch die Basis.
trigExtended|Winkel lassen sich in Grad oder im Bogenmaß ausdrücken. Eine halbe Umdrehung hat 180° beziehungsweise π Radiant.|Multipliziere einen Gradwert mit π/180. Kürze den Bruch vor π. Für den umgekehrten Weg multiplizierst du mit 180/π.|Achte am Taschenrechner auf Grad- oder Bogenmaßmodus. Eine korrekte Formel mit falschem Winkelmodus führt zu einem falschen Zahlenwert.
derivative|Die Ableitung beschreibt die momentane Änderungsrate und die Steigung der Tangente. Sie ist selbst eine Funktion, deren Wert von der Stelle abhängt.|Mit der Potenzregel wird aus axⁿ die Ableitung an·xⁿ⁻¹. Bestimme erst die Ableitungsfunktion und setze dann die gefragte Stelle ein. Konstanten fallen beim Ableiten weg. Bei Produkten gilt (uv)′ = u′v + uv′; bei verketteten Funktionen multiplizierst du die äußere Ableitung mit der inneren Ableitung.|Der Exponent wird um eins kleiner, der alte Exponent wird zum Faktor. f(x₀) und f′(x₀) sind verschiedene Größen.
combinations|Kombinatorik zählt Möglichkeiten, ohne sie alle einzeln aufzulisten. Entscheidend ist, ob die Reihenfolge eine Rolle spielt und ob Wiederholung erlaubt ist.|Für zwei verschiedene ausgewählte Personen gibt es n·(n−1) geordnete Paare. Ist die Reihenfolge egal, teilst du durch 2. Für eine Anordnung aller n Objekte verwendest du n!.|Zuerst die Situation einordnen, erst danach eine Formel einsetzen. Eine Gruppe aus A und B ist dieselbe Gruppe wie aus B und A.
binomial|Eine Binomialverteilung zählt Erfolge in einer festen Anzahl unabhängiger Versuche mit gleichbleibender Erfolgswahrscheinlichkeit.|Für genau k Erfolge bestimmst du zuerst die Zahl der Anordnungen. Multipliziere sie mit pᵏ und (1−p)ⁿ⁻ᵏ. Der Erwartungswert ist n·p.|Genau k, mindestens k und höchstens k sind unterschiedliche Ereignisse. Ohne Unabhängigkeit oder konstantes p passt das Binomialmodell nicht ohne Weiteres.
statistics|Statistik verdichtet Daten, aber einzelne Kennwerte erzählen nicht die ganze Geschichte. Verteilung, Streuung, Stichprobenauswahl und Darstellung beeinflussen die Interpretation.|Berechne passende Lage- und Streuungsmaße und vergleiche sie gemeinsam. Kontrolliere bei Diagrammen die Achsen und bei Umfragen die Auswahl der Befragten.|Gleicher Mittelwert bedeutet nicht gleiche Verteilung. Eine große, aber einseitig ausgewählte Stichprobe kann trotzdem verzerrt sein.
sphere|Eine Kugel ist die Menge aller Raumpunkte bis zu einem festen Abstand vom Mittelpunkt. Radius und Durchmesser beschreiben ihre Größe.|Für das Volumen gilt V = 4πr³/3. Berechne zunächst r³, multipliziere mit 4π und teile durch 3. Die Oberfläche wird dagegen mit 4πr² berechnet.|Eine Verdopplung des Radius verachtfacht das Volumen, weil der Radius in dritter Potenz eingeht. Oberfläche und Volumen skalieren verschieden.
change|Die mittlere Änderungsrate misst die durchschnittliche Veränderung einer Funktion auf einem Intervall. Geometrisch ist sie die Steigung der Sekante zwischen zwei Punkten.|Bestimme die beiden Funktionswerte. Berechne ihre Differenz und teile durch die Differenz der x-Werte. Halte bei beiden Differenzen dieselbe Reihenfolge ein.|Mittlere und momentane Änderungsrate sind nicht dasselbe. Ein Intervall mit gleichen Grenzen ist für den Differenzenquotienten nicht erlaubt.
extrema|An einer lokalen Extremstelle ist ein Funktionswert in seiner Umgebung besonders klein oder groß. Eine waagerechte Tangente liefert zunächst nur einen Kandidaten.|Bestimme die Ableitung und setze sie gleich null. Prüfe danach beispielsweise das Vorzeichen der zweiten Ableitung. Bei einer nach oben geöffneten Parabel liegt am Scheitel ein Minimum.|f′ = 0 allein beweist noch kein Extremum. Bei f(x) = x³ ist die Ableitung in 0 null, ohne dass dort ein Extrempunkt liegt.
integral|Ein bestimmtes Integral beschreibt eine orientierte Flächenbilanz. Eine Stammfunktion kehrt das Ableiten um. Der Hauptsatz verbindet beide Ideen.|Bestimme eine Stammfunktion F. Setze zuerst die obere und dann die untere Grenze ein. Berechne F(b) − F(a). Für geometrische Flächen musst du Vorzeichenwechsel beachten.|Vergiss den unteren Grenzwert nicht. Flächen unter der x-Achse tragen zum orientierten Integral negativ bei.
vectors|Ein Vektor beschreibt eine gerichtete Verschiebung. Im Raum besitzt er drei Komponenten für die drei Koordinatenrichtungen.|Addiere Vektoren komponentenweise: x mit x, y mit y und z mit z. Beim Skalieren wird jede Komponente mit demselben Faktor multipliziert.|Ein Punkt beschreibt einen Ort, ein Vektor eine Verschiebung. Auch wenn beide durch Zahlenpaare oder Zahlentripel dargestellt werden, haben sie unterschiedliche Rollen.
dot|Das Skalarprodukt verknüpft zwei Vektoren zu einer Zahl. Es verbindet Rechnen mit geometrischen Aussagen über Winkel und Senkrechtstehen.|Multipliziere passende Komponenten und addiere die Produkte. Für zwei von null verschiedene Vektoren gilt bei Skalarprodukt null: Sie stehen senkrecht aufeinander.|Das Ergebnis ist eine Zahl, kein Vektor. Der Nullvektor besitzt keine eindeutige Richtung; die übliche Winkelberechnung ist für ihn nicht definiert.
lines|Eine Raumgerade lässt sich durch einen Stützpunkt und einen Richtungsvektor beschreiben. Ein Parameter legt fest, wie weit du in diese Richtung gehst.|Setze den Parameter in jede Koordinate ein. Multipliziere zuerst die Richtungskomponente mit dem Parameter und addiere danach die entsprechende Stützkoordinate.|Derselbe Parameter muss für alle Koordinaten verwendet werden. Die Übungen beginnen mit Geradenpunkten; vollständige Ebenenberechnungen sind ein eigener Vertiefungsschritt.
distance|Der Abstand zweier Punkte ist die Länge ihres Verbindungsvektors. Im Raum nutzt du den Satz des Pythagoras in drei Koordinatenrichtungen.|Bilde die Koordinatendifferenzen. Quadriere jede Differenz, addiere die Quadrate und ziehe die Quadratwurzel. Der Abstand ist immer nichtnegativ.|Addiere nicht nur die Beträge der Unterschiede. Das würde einen Weg entlang der Achsen messen, nicht die direkte räumliche Verbindung.
matrices|Eine Matrix ist ein rechteckiges Zahlenschema. Bei einer Matrix-Vektor-Multiplikation entsteht jede Ergebniskomponente aus einer Zeile der Matrix.|Multipliziere jeden Zeileneintrag mit der passenden Vektorkomponente und addiere die Produkte. Wiederhole das für jede Zeile. Die inneren Dimensionen müssen übereinstimmen.|Matrixmultiplikation ist keine stellenweise Multiplikation. Die Reihenfolge der Faktoren darf im Allgemeinen nicht vertauscht werden.
hypothesis|Ein Hypothesentest entscheidet anhand einer Stichprobe, ob eine Nullhypothese verworfen wird. Er liefert eine Entscheidung unter Unsicherheit und keinen endgültigen Wahrheitsbeweis.|Unterscheide zwei Fehlerarten: Eine wahre H₀ verwerfen ist Fehler 1. Art; eine falsche H₀ nicht verwerfen ist Fehler 2. Art. Das Signifikanzniveau begrenzt die Wahrscheinlichkeit des ersten Fehlers.|Nichtverwerfen beweist H₀ nicht. In dieser Lerneinheit übst du die Begriffe und Entscheidungslogik; numerische Tests benötigen zusätzlich ein festgelegtes Modell und eine Ablehnungsregion.
`.trim();
export const lessonGuides = Object.fromEntries(lessonTexts.split('\n').map(line=>{const [id,idea,method,pitfall]=line.split('|');return [id,{idea,method,pitfall}];}));
const lessonStep=(label,before,value,after,why)=>({label,before,value,after,why});
export function workedTask(grade, topic, {rng=Math.random,easy=false}={}) {
 const r=(a,b)=>rand(a,b,rng), pick=a=>a[r(0,a.length-1)], n=()=>r(2,easy?5:9);
 const f=format, steps=[];let prompt='',visual=null;
 const step=(...args)=>steps.push(lessonStep(...args));
 const a=n(),b=n(),c=n();
 switch(topic.id){
 case 'count': {const x=r(2,grade===1?18:grade===2?98:grade===3?998:999998);prompt=`Bestimme Vorgänger und Nachfolger von ${f(x)}.`;step('Vorgänger',`${f(x)} − 1 = `,x-1,'','Gehe auf dem Zahlenstrahl einen Schritt nach links.');step('Nachfolger',`${f(x)} + 1 = `,x+1,'','Gehe einen Schritt nach rechts.');break;}
 case 'place': {const x=grade>=3?r(100,999):r(10,19+(grade===1?0:80)),tens=Math.floor(x/10)%10;prompt=`Zerlege ${x} in Stellenwerte.`;if(grade>=3)step('Hunderter',`${x} enthält `,Math.floor(x/100),' Hunderter','Die dritte Stelle von rechts zählt Hunderter.');step('Zehner',`${x} enthält `,tens,' Zehner','Die zweite Stelle von rechts zählt Zehner.');step('Einer',`${x} enthält `,x%10,' Einer','Die letzte Stelle zählt Einer.');break;}
 case 'add': case 'subtract': {if(grade>=3){const plus=topic.id==='add',x=grade===3?r(200,800):r(1200,8000),y=grade===3?r(12,99):r(100,999);prompt=`Berechne ${f(x)} ${plus?'+':'−'} ${y} schriftlich.`;let carry=0;const width=String(x).length;for(let i=0;i<width;i++){const power=10**i,dx=Math.floor(x/power)%10,dy=Math.floor(y/power)%10,label=['Einer','Zehner','Hunderter','Tausender'][i];if(plus){const sum=dx+dy+carry,next=Math.floor(sum/10);step(label,`${dx} + ${dy} + ${carry} Übertrag = `,sum,`; ${sum%10} schreiben${next?`, ${next} übertragen`:''}`,'Gleiche Stellen stehen untereinander. Zehn Einheiten werden zur nächsten Stelle gebündelt.');carry=next;}else{const available=dx-carry,borrow=available<dy?1:0,diff=available+borrow*10-dy;step(label,`${dx} − ${carry} vom Entbündeln ${borrow?'+ 10 neue Einheiten ':''}− ${dy} = `,diff,'',borrow?'Entbündle eine Einheit der nächsthöheren Stelle. Sie entspricht hier zehn Einheiten.':'Ziehe die entsprechende Ziffer ab und berücksichtige vorheriges Entbündeln.');carry=borrow;}}step('Gesamtergebnis',`${f(x)} ${plus?'+':'−'} ${y} = `,plus?x+y:x-y,'','Lies die Ergebnisziffern stellenrichtig zusammen und kontrolliere die Größenordnung.');break;}const start=topic.id==='add'?(grade===1?8:grade===2?38:grade===3?238:1238):(grade===1?12:grade===2?42:grade===3?242:1242),offset=grade===1?r(0,1):r(0,5)*10,x=start+offset,k=r(3,9),plus=topic.id==='add',first=plus?10-x%10:x%10,rem=k-first;prompt=`Berechne ${f(x)} ${plus?'+':'−'} ${k} schrittweise.`;step('Erster Teil',`Bis zum ${plus?'nächsten':'vorigen'} Zehner: `,first,'','Nutze einen vollen Zehner als Zwischenstation.');step('Zwischenergebnis',`${x} ${plus?'+':'−'} ${first} = `,plus?x+first:x-first,'','Rechne den einfachen Teil zuerst.');step('Ergebnis',`${plus?x+first:x-first} ${plus?'+':'−'} (${rem}) = `,plus?x+k:x-k,'',`Vom zweiten Summanden beziehungsweise Subtrahenden bleiben ${rem}. Rechne jetzt den verbleibenden Teil.`);break;}
 case 'missing': prompt=`Welche Zahl passt? □ + ${a} = ${a+b}`;step('Umkehraufgabe',`${a+b} − ${a} = `,b,'','Ziehe den bekannten Summanden von der Summe ab.');step('Probe',`${b} + ${a} = `,a+b,'','Setze deine Zahl in die ursprüngliche Rechnung ein.');break;
 case 'sequence': {const s=r(0,5),d=r(1,grade===1?3:8),seq=[s,s+d,s+2*d,s+3*d];prompt=`Setze die Zahlenfolge fort: ${seq.join(', ')}, …`;step('Schrittweite',`${s+d} − ${s} = `,d,'','Bestimme den Abstand und prüfe ihn an einem weiteren Zahlenpaar.');step('Nächste Zahl',`${s+3*d} + ${d} = `,s+4*d,'','Nutze dieselbe Schrittweite noch einmal.');step('Übernächste Zahl',`${s+4*d} + ${d} = `,s+5*d,'','Die Regel bleibt gleich.');break;}
 case 'shapes': {const [name,sides,square]=pick([['Quadrat',4,true],['Dreieck',3,false],['Rechteck',4,true],['Fünfeck',5,false],['Kreis',0,false]]);prompt=`Untersuche die Form „${name}“. Wie viele gerade Seiten und Ecken hat sie?`;step('Gerade Seiten','Anzahl der geraden Seiten: ',sides,'',name==='Kreis'?'Der Kreisrand ist gekrümmt und besteht nicht aus geraden Seiten.':'Jede gerade Randstrecke ist eine Seite.');step('Ecken','Anzahl der Ecken: ',sides,'',name==='Kreis'?'Ein Kreis hat keine Ecken.':'An jeder Ecke treffen zwei Seiten aufeinander.');visual={kind:'shape',square,name};break;}
 case 'numberLine': prompt=`Wie weit ist es auf dem Zahlenstrahl von ${a} bis ${a+b}?`;step('Größere Zahl','Rechter Endpunkt: ',a+b,'','Die größere Zahl liegt weiter rechts.');step('Abstand',`${a+b} − ${a} = `,b,' Schritte','Zähle die Zwischenräume.');break;
 case 'story': {const people=grade===1?r(2,5):a,each=grade===1?r(2,3):b,used=r(1,each-1);prompt=`${people} Kinder erhalten je ${each} Sticker für ihr Lernheft. Jedes klebt ${used} Sticker ein. Wie viele ungeklebt gebliebene Sticker haben alle zusammen?`;step('Pro Kind übrig',`${each} − ${used} = `,each-used,' Sticker','Berechne zuerst den Rest bei einer Person.');step('Insgesamt übrig',grade===1?`${Array.from({length:people},()=>each-used).join(' + ')} = `:`${people} · ${each-used} = `,people*(each-used),' Sticker',grade===1?`Zähle ${people} gleich große Gruppen mit jeweils ${each-used} Sticker(n).`:'Multipliziere den Rest mit der Anzahl der Kinder.');break;}
 case 'multiply': {const x=grade<=2?a:10+a;const factor=grade>=4?10+b:b;prompt=`Berechne das Produkt ${x} · ${factor}.`;if(grade<=2){step('Erste zwei Gruppen',`${b} + ${b} = `,2*b,'','Zwei gleich große Gruppen werden zusammengezählt.');step('Alle Gruppen',`${Array.from({length:a},()=>b).join(' + ')} = `,a*b,'',`Du addierst ${a}-mal dieselbe Zahl.`);}else{step('Zehnerprodukt',`10 · ${factor} = `,10*factor,'','Zerlege den ersten Faktor in 10 und den Rest.');step('Einerprodukt',`${a} · ${factor} = `,a*factor,'','Multipliziere auch den Rest.');step('Ergebnis',`${10*factor} + ${a*factor} = `,(10+a)*factor,'','Addiere beide Teilprodukte.');}break;}
 case 'divide': {if(grade>=4){const d=r(2,4),q=r(102,205),x=d*q;prompt=`Dividiere ${x} schriftlich durch ${d}.`;let rem=0;for(const [i,digit]of [...String(x)].entries()){const partial=rem*10+Number(digit),quot=Math.floor(partial/d);rem=partial%d;step(`Teilquotient an Stelle ${i+1}`,`${partial} : ${d} ergibt `,quot,`; Rest ${rem}`,'Teile die aktuelle Teilzahl. Nimm den Rest zur nächsten heruntergeholten Ziffer mit. Eine null im Quotienten darf nicht fehlen.');}step('Gesamtquotient',`${x} : ${d} = `,q,'','Füge die Quotientenziffern zusammen und kontrolliere mit der Multiplikation.');break;}const rest=grade===3?r(1,b-1):0,x=a*b+rest;prompt=`Teile ${x} durch ${b}${rest?' mit Rest':''}.`;step('Passendes Vielfaches',`${a} · ${b} = `,a*b,'',`Suche das größte Vielfache von ${b}, das nicht größer als ${x} ist.`);step('Quotient',`${x} : ${b} ergibt `,a,' ganze Gruppen','Die Zahl der ganzen Gruppen ist der Quotient.');if(rest)step('Rest',`${x} − ${a*b} = `,rest,'','Der Rest ist kleiner als der Divisor.');else step('Probe',`${a} · ${b} = `,x,'','Die Multiplikation bestätigt das Ergebnis.');break;}
 case 'money': {const price=a*100+b*10,paid=1000;prompt=`Ein digitales Lernheft kostet ${f(price/100)} €. Du bezahlst 10 €. Berechne das Rückgeld.`;step('Preis in Cent',`${f(price/100)} € = `,price,' ct','Ein Euro entspricht 100 Cent.');step('Rückgeld in Cent',`1000 − ${price} = `,1000-price,' ct','Ziehe den Preis vom bezahlten Betrag ab.');step('Rückgeld in Euro',`${1000-price} : 100 = `,(1000-price)/100,' €','Wandle Cent wieder in Euro um.');break;}
 case 'clock': {const h=r(1,11),m=pick([15,30,45]);prompt=`Eine analoge Uhr zeigt den kurzen Zeiger nach ${h} und den langen Zeiger auf ${m/5}. Lies die Uhrzeit ab.`;step('Stunden','Ganze Stunden: ',h,' Uhr','Lies die zuletzt erreichte Stundenzahl am kurzen Zeiger.');step('Minuten',`${m/5} · 5 = `,m,' Minuten','Ein Abstand von einer Uhrzahl zur nächsten entspricht fünf Minuten.');visual={kind:'clock',h,m};break;}
 case 'time': prompt=`Ein Lernprojekt dauert ${a} Stunden und ${b*5} Minuten. Wie viele Minuten sind das insgesamt?`;step('Stunden umrechnen',`${a} · 60 = `,a*60,' min','Jede Stunde hat 60 Minuten.');step('Gesamtdauer',`${a*60} + ${b*5} = `,a*60+b*5,' min','Addiere die zusätzlichen Minuten.');break;
 case 'units': prompt=`Rechne ${a} m und ${b} cm zusammen in Zentimeter um.`;step('Meter umrechnen',`${a} · 100 = `,a*100,' cm','Ein Meter entspricht 100 Zentimetern.');step('Gesamtlänge',`${a*100} + ${b} = `,a*100+b,' cm','Jetzt sind beide Angaben in derselben Einheit.');break;
 case 'perimeter': prompt=`Ein rechteckiger Schulgarten ist ${a} m lang und ${b} m breit. Wie viel Zaun wird ohne Tor benötigt?`;step('Zwei Nachbarseiten',`${a} + ${b} = `,a+b,' m','Länge und Breite bilden die Hälfte des Randes.');step('Gesamter Umfang',`2 · ${a+b} = `,2*(a+b),' m','Jede Seitenlänge kommt zweimal vor.');visual={kind:'rectangle',a,b};break;
 case 'calendar': {const names=['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'],start=r(0,6),days=r(8,20);prompt=`Heute ist ${names[start]}. Welcher Wochentag ist in ${days} Tagen?`;step('Volle Wochen',`${days} : 7 ergibt `,Math.floor(days/7),' volle Wochen','Jede volle Woche führt zum gleichen Wochentag zurück.');step('Übrige Tage',`${days} − ${Math.floor(days/7)*7} = `,days%7,' Tage','Nur der Rest verändert den Wochentag.');step('Wochentag','In dieser Zeit ist ',names[(start+days)%7],'','Gehe die übrigen Tage weiter.');break;}
 case 'round': {const x=r(11,98)*10+r(1,9),rounded=Math.round(x/10)*10;prompt=`Runde ${x} auf Zehner.`;step('Entscheidende Ziffer','Einerziffer: ',x%10,'','Beim Runden auf Zehner entscheidet die Einerziffer.');step('Gerundeter Wert',`${x} ≈ `,rounded,'','Bei 5 bis 9 aufrunden, bei 0 bis 4 abrunden.');break;}
 case 'fraction': {const den=r(2,8),num=r(1,den-1),whole=den*a;prompt=`Berechne ${num}/${den} von ${whole}.`;step('Ein Teil',`${whole} : ${den} = `,a,'','Teile das Ganze in gleich große Teile.');step('Gesuchter Anteil',`${a} · ${num} = `,a*num,'','Nimm so viele Teile, wie der Zähler angibt.');visual={kind:'fraction',num,den};break;}
 case 'area': prompt=`Ein rechteckiges Solarmodul ist ${a} m lang und ${b} m breit. Berechne seine Fläche.`;step('Quadrate pro Reihe','Pro Reihe liegen ',a,' Einheitsquadrate','Die Länge gibt die Zahl der Einheitsquadrate in einer Reihe an.');step('Gesamtfläche',`${a} · ${b} = `,a*b,' m²',`Es gibt ${b} solcher Reihen.`);visual={kind:'rectangle',a,b};break;
 case 'probability': {const k=r(1,5);prompt=`Ein fairer Würfel wird geworfen. Wie wahrscheinlich ist eine Zahl höchstens ${k}?`;step('Günstige Ergebnisse','Anzahl günstiger Zahlen: ',k,'',`Die Zahlen 1 bis ${k} erfüllen die Bedingung.`);step('Mögliche Ergebnisse','Alle gleich wahrscheinlichen Ergebnisse: ',6,'','Ein Würfel hat sechs Seiten.');step('Wahrscheinlichkeit',`${k} / 6 = `,`${k}/6`,'','Teile günstig durch möglich. Gleichwertige Brüche werden akzeptiert.');break;}
 case 'data': {const vals=[a,b,c];prompt=`Drei Solarmodule erzeugen heute ${a}, ${b} und ${c} kWh. Wie viel ist das zusammen?`;step('Erste zwei Module',`${a} + ${b} = `,a+b,' kWh','Addiere Werte mit derselben Einheit.');step('Alle Module',`${a+b} + ${c} = `,a+b+c,' kWh','Ergänze den dritten Wert.');visual={kind:'bars',vals};break;}
 case 'solids': {const count=r(1,5);prompt=`${count} Würfel liegen getrennt nebeneinander. Zähle alle Flächen, Kanten und Ecken zusammen; die Würfel sind nicht verbunden.`;step('Flächen insgesamt',`${count} · 6 = `,6*count,' Flächen','Jeder einzelne Würfel hat sechs Flächen.');step('Kanten insgesamt',`${count} · 12 = `,12*count,' Kanten','Jeder Würfel hat zwölf Kanten.');step('Ecken insgesamt',`${count} · 8 = `,8*count,' Ecken','Jeder Würfel hat acht Ecken.');break;}
 case 'operations': prompt=`Berechne ${a} + ${b} · ${c} und vergleiche mit (${a} + ${b}) · ${c}.`;step('Punkt vor Strich',`${b} · ${c} = `,b*c,'','Ohne Klammer hat die Multiplikation Vorrang.');step('Erster Term',`${a} + ${b*c} = `,a+b*c,'','Addiere das Produkt zum ersten Summanden.');step('Klammerterm',`(${a} + ${b}) · ${c} = `,(a+b)*c,'','Hier hat die Klammer Vorrang vor der Multiplikation.');break;
 case 'divisibility': {const x=r(11,99),d=3;prompt=`Prüfe, ob ${x} durch ${d} teilbar ist.`;step('Quersumme',`${Math.floor(x/10)} + ${x%10} = `,Math.floor(x/10)+x%10,'','Für die Teilbarkeit durch 3 zählt die Summe der Ziffern.');step('Rest',`${x} bei Division durch 3: Rest `,x%3,'','Der Rest ist derselbe wie bei der Quersumme.');step('Entscheidung','Teilbar? (ja/nein): ',x%3===0?'ja':'nein','','Nur Rest null bedeutet Teilbarkeit.');break;}
 case 'prime': {const x=pick([11,13,17,19,21,25,27,33]),prime=[11,13,17,19].includes(x),div=x%3===0?3:5;prompt=`Ist ${x} eine Primzahl?`;step('Teiler 2','Durch 2 teilbar? (ja/nein): ','nein','','Alle hier ausgewählten Zahlen sind ungerade.');step('Weitere Prüfung','Durch 3 oder 5 teilbar? (ja/nein): ',prime?'nein':'ja','',prime?'Bei diesen Zahlen genügen 2 und 3 beziehungsweise zusätzlich 5 als mögliche Primteiler bis zur Wurzel.':`${x} hat den echten Teiler ${div}.`);step('Entscheidung','Primzahl? (ja/nein): ',prime?'ja':'nein','','Eine Primzahl hat nur 1 und sich selbst als positive Teiler.');break;}
 case 'volume': prompt=`Berechne das Volumen einer Aufbewahrungsbox mit ${a} cm Länge, ${b} cm Breite und ${c} cm Höhe.`;step('Grundfläche',`${a} · ${b} = `,a*b,' cm²','Eine Schicht hat diese Fläche.');step('Volumen',`${a*b} · ${c} = `,a*b*c,' cm³','Multipliziere mit der Anzahl der ein Zentimeter hohen Schichten.');break;
 case 'symmetry': prompt=`Spiegle den Punkt P(${a}, ${b}) an der y-Achse.`;step('x-Koordinate',`−(${a}) = `,-a,'','Die waagerechte Richtung kehrt sich um.');step('y-Koordinate','Unveränderte Höhe: ',b,'','Die Höhe bleibt beim Spiegeln an der y-Achse gleich.');break;
 case 'angles': {const x=pick([30,45,75,90,110,135]);prompt=`Ordne einen Winkel von ${x}° ein.`;step('Vergleich','Kleiner als 90°? (ja/nein): ',x<90?'ja':'nein','','Vergleiche mit einer Vierteldrehung.');step('Winkelart','spitz, recht oder stumpf: ',x<90?'spitz':x===90?'recht':'stumpf','','90° ist recht, darunter spitz, darüber bis 180° stumpf.');break;}
 case 'gcd': {const x=a*2,y=a*3;prompt=`Bestimme ggT und kgV von ${x} und ${y}.`;step('Größter gemeinsamer Teiler','ggT = ',a,'',`${x} = 2 · ${a} und ${y} = 3 · ${a}. 2 und 3 haben keinen weiteren gemeinsamen Teiler.`);step('Produkt',`${x} · ${y} = `,x*y,'','Bereite die Formel für das kgV vor.');step('Kleinstes gemeinsames Vielfaches',`${x*y} : ${a} = `,x*y/a,'','Für positive ganze Zahlen ist kgV = Produkt / ggT.');break;}
 case 'negative': prompt=`Die Temperatur ist −${a} °C und steigt um ${a+b} °C. Wie warm ist es danach?`;step('Bis null','Benötigter Anstieg bis 0 °C: ',a,' °C','Gehe zuerst vom negativen Wert bis null.');step('Restlicher Anstieg',`${a+b} − ${a} = `,b,' °C','Der übrige Anstieg liegt über null.');step('Endtemperatur',`−${a} + ${a+b} = `,b,' °C','Die Temperatur ist jetzt positiv.');break;
 case 'fractions': {const x=r(1,3),y=r(1,3);prompt=`Addiere ${x}/4 + ${y}/6.`;step('Erster Zähler',`${x}/4 = □/12; Zähler: `,x*3,'','Erweitere den ersten Bruch mit 3.');step('Zweiter Zähler',`${y}/6 = □/12; Zähler: `,y*2,'','Erweitere den zweiten Bruch mit 2.');step('Summe',`(${x*3} + ${y*2}) / 12 = `,`${x*3+y*2}/12`,'','Addiere die Zähler, behalte den gemeinsamen Nenner.');break;}
 case 'fractionProduct': {const divide=r(0,1);prompt=`Berechne ${a}/${b} ${divide?':':'·'} ${c}/2.`;if(divide){step('Kehrwert',`Kehrwert von ${c}/2: `,`2/${c}`,'','Nur der zweite Bruch wird umgedreht.');step('Zählerprodukt',`${a} · 2 = `,a*2,'','Multipliziere die Zähler.');step('Ergebnis',`${a*2} / (${b} · ${c}) = `,`${a*2}/${b*c}`,'','Multipliziere auch die Nenner und kürze bei Bedarf.');}else{step('Zählerprodukt',`${a} · ${c} = `,a*c,'','Multipliziere die beiden Zähler miteinander.');step('Nennerprodukt',`${b} · 2 = `,b*2,'','Multipliziere die beiden Nenner miteinander.');step('Ergebnis',`${a*c}/${b*2} = `,`${a*c}/${b*2}`,'','Fasse die Produkte zum Bruch zusammen; gleichwertige gekürzte Brüche sind erlaubt.');}break;}
 case 'decimal': {const x=a*10+b,y=c*10+a;prompt=`Addiere ${f(x/100)} + ${f(y/100)}.`;step('Erste Zahl in Hundertsteln',`${f(x/100)} · 100 = `,x,'','Beide Zahlen werden als Hundertstel betrachtet.');step('Summe der Hundertstel',`${x} + ${y} = `,x+y,'','Addiere die ganzen Anzahlen der Hundertstel.');step('Dezimalergebnis',`${x+y} : 100 = `,(x+y)/100,'','Schreibe die Summe wieder als Dezimalzahl.');break;}
 case 'percent': {const g=a*20,p=pick([10,20,25]);prompt=`Kopfhörer kosten ${g} €. Es gibt ${p} % Rabatt. Berechne den neuen Preis.`;step('Ein Prozent',`${g} : 100 = `,g/100,' €','Der Grundwert wird in hundert gleiche Teile zerlegt.');step('Rabattbetrag',`${f(g/100)} · ${p} = `,g*p/100,' €','Nimm den gefragten Prozentsatz dieser Teile.');step('Neuer Preis',`${g} − ${f(g*p/100)} = `,g*(100-p)/100,' €','Ziehe den Rabatt vom ursprünglichen Preis ab.');break;}
 case 'proportion': prompt=`${a} digitale Lernkarten-Sets kosten ${a*b} €. Was kosten ${c} Sets bei gleichem Einzelpreis?`;step('Preis eines Sets',`${a*b} : ${a} = `,b,' €','Gehe zuerst auf eine Einheit zurück.');step('Preis der gesuchten Menge',`${b} · ${c} = `,b*c,' €','Multipliziere den Einzelpreis mit der neuen Menge.');break;
 case 'inverse': prompt=`${a} gleich schnelle Roboter benötigen ${b*2} Stunden für einen Auftrag. Wie lange benötigen ${a*2} Roboter?`;step('Arbeitsmenge',`${a} · ${b*2} = `,a*b*2,' Roboterstunden','Unter diesen Annahmen bleibt das Produkt konstant.');step('Neue Dauer',`${a*b*2} : ${a*2} = `,b,' Stunden','Teile durch die neue Zahl gleich schneller Roboter.');break;
 case 'circle': prompt=`Ein Kreis hat Radius ${a} cm. Berechne den Umfang mit π ≈ 3,14.`;step('Durchmesser',`2 · ${a} = `,2*a,' cm','Der Durchmesser ist doppelt so groß wie der Radius.');step('Umfang',`3,14 · ${2*a} = `,+(3.14*2*a).toFixed(2),' cm','Multipliziere den Durchmesser mit π.');break;
 case 'mean': case 'statistics': {const vals=[a,a+2,a+7];prompt=`Drei Lernzeiten sind ${vals.join(', ')} Minuten. Berechne Mittelwert und Spannweite. Gib den Mittelwert als Bruch an, falls nötig.`;step('Summe',`${vals.join(' + ')} = `,3*a+9,' min','Fasse die gesamte Zeit zusammen.');step('Mittelwert',`${3*a+9} : 3 = `,a+3,' min','Verteile die Summe auf drei Werte.');step('Spannweite',`${a+7} − ${a} = `,7,' min','Ziehe den kleinsten vom größten Wert ab.');break;}
 case 'triangleArea': prompt=`Ein dreieckiges Segel hat Grundseite ${a} m und senkrechte Höhe ${b} m. Berechne seine Fläche.`;step('Passendes Rechteck',`${a} · ${b} = `,a*b,' m²','Dieses Produkt ist die doppelte Dreiecksfläche.');step('Dreiecksfläche',`${a*b} : 2 = `,a*b/2,' m²','Ein Dreieck mit gleicher Grundseite und Höhe hat die halbe Fläche.');break;
 case 'terms': prompt=`Fasse ${a}x + ${b}x + ${c} zusammen.`;step('Faktor vor x',`${a} + ${b} = `,a+b,'','Nur gleichartige x-Terme werden zusammengefasst.');step('Konstante','Verbleibender konstanter Summand: ',c,'',`Die Konstante hat keinen Faktor x. Der Term lautet (${a+b})x + ${c}.`);break;
 case 'equation': {const x=n(),rhs=a*x+b;prompt=`Löse ${a}x + ${b} = ${rhs} und prüfe dein Ergebnis.`;step('Konstante entfernen',`${a}x = ${rhs} − ${b} = `,a*x,'','Subtrahiere auf beiden Seiten dieselbe Zahl.');step('x bestimmen',`x = ${a*x} : ${a} = `,x,'','Teile beide Seiten durch den Faktor vor x.');step('Probe',`${a} · ${x} + ${b} = `,rhs,'','Das Ergebnis muss der rechten Seite entsprechen.');break;}
 case 'distribute': prompt=`Multipliziere aus: ${a}(${b}x + ${c}).`;step('x-Faktor',`${a} · ${b} = `,a*b,'','Multipliziere den äußeren Faktor mit dem x-Faktor.');step('Konstante',`${a} · ${c} = `,a*c,'',`Auch der zweite Summand wird multipliziert: ${a*b}x + ${a*c}.`);break;
 case 'linear': {const x=r(-3,4);prompt=`f(x) = ${a}x + ${b}. Berechne f(${x}).`;step('Produkt',`${a} · (${x}) = `,a*x,'','Setze den x-Wert ein und rechne zuerst die Multiplikation.');step('Funktionswert',`${a*x} + ${b} = `,a*x+b,'','Addiere den y-Achsenabschnitt.');visual={kind:'line',m:a,b};break;}
 case 'triangle': {const x=a*5,y=b*5;prompt=`Ein Dreieck hat Winkel ${x}° und ${y}°. Bestimme den dritten Winkel.`;step('Bekannte Winkel',`${x} + ${y} = `,x+y,'°','Addiere die zwei gegebenen Winkel.');step('Dritter Winkel',`180 − ${x+y} = `,180-x-y,'°','Die Summe aller Innenwinkel ist 180°.');break;}
 case 'congruence': {const alpha=r(20,70);prompt=`C liegt auf dem Halbkreis über dem Durchmesser AB. Winkel A im Dreieck ABC ist ${alpha}°. Bestimme die Winkel C und B.`;step('Thaleswinkel','Winkel C = ',90,'°','Ein Winkel über dem Halbkreisdurchmesser ist recht.');step('Dritter Winkel',`180 − 90 − ${alpha} = `,90-alpha,'°','Die Winkelsumme im Dreieck beträgt 180°.');break;}
 case 'inequality': prompt=`Bestimme den Lösungsbereich der Ungleichung −${a}x < ${a*b}.`;step('Grenzwert',`${a*b} : (−${a}) = `,-b,'','Teile die rechte Seite durch den negativen x-Faktor.');step('Zeichen','Zeichen nach dem Teilen (< oder >): ','>','','Beim Teilen durch eine negative Zahl kehrt sich das Zeichen um.');step('Lösungsgrenze','Es gilt x > ',-b,'','Alle Zahlen größer als die Grenze erfüllen die Ungleichung.');break;
 case 'construction': {const length=a*2;prompt=`Eine Strecke AB ist ${length} cm lang. Du konstruierst ihre Mittelsenkrechte. Bestimme die Lage des Schnittpunkts M und den Schnittwinkel.`;step('Abstand AM',`${length} : 2 = `,a,' cm','Die Mittelsenkrechte schneidet die Strecke in ihrem Mittelpunkt.');step('Abstand BM',`${length} − ${a} = `,a,' cm','M hat denselben Abstand von beiden Endpunkten.');step('Schnittwinkel','Winkel zwischen AB und der Mittelsenkrechten: ',90,'°','Senkrecht bedeutet rechter Winkel.');break;}
 case 'systems': {const x=n(),y=n(),u=x+y,v=2*x-y;prompt=`Löse das Gleichungssystem: x + y = ${u}; 2x − y = ${v}.`;step('Gleichungen addieren',`3x = ${u} + (${v}) = `,3*x,'','Die y-Terme heben sich auf.');step('x bestimmen',`${3*x} : 3 = `,x,'','Teile durch den Faktor 3.');step('y bestimmen',`${u} − ${x} = `,y,'','Setze x in die erste Gleichung ein und prüfe beide.');break;}
 case 'pythagoras': {const k=r(1,4);prompt=`Ein rechtwinkliges Dreieck hat Katheten ${3*k} cm und ${4*k} cm. Berechne die Hypotenuse.`;step('Erstes Quadrat',`${3*k}² = `,9*k*k,' cm²','Quadriere die erste Kathete.');step('Summe der Quadrate',`${9*k*k} + ${4*k}² = `,25*k*k,' cm²','Addiere das Quadrat der zweiten Kathete.');step('Hypotenuse',`√${25*k*k} = `,5*k,' cm','Ziehe die nichtnegative Quadratwurzel.');break;}
 case 'roots': prompt=`Bestimme die nichtnegative Quadratwurzel √${a*a}.`;step('Passende Quadratzahl','Welche nichtnegative Zahl ergibt beim Quadrieren den Radikanden? ',a,'',`Die passende Quadratzahl findest du mit ${a} · ${a} = ${a*a}.`);step('Probe',`${a} · ${a} = `,a*a,'','Das Quadrat bestätigt die Wurzel.');break;
 case 'rational': prompt=`f(x) = ${a*b}/x. Berechne f(${a}) und prüfe, ob die Stelle erlaubt ist.`;step('Definitionsbereich','Ist der eingesetzte x-Wert erlaubt? (ja/nein): ','ja','','Der eingesetzte Wert ist nicht null.');step('Funktionswert',`${a*b} : ${a} = `,b,'','Teile den Zähler durch den eingesetzten Wert.');break;
 case 'interest': {const k=a*100,p=pick([2,4,5]),z=k*p/100,k1=k+z,z2=k1*p/100;prompt=`${k} € werden zwei Jahre zu ${p} % jährlich angelegt. Die Zinsen werden mitverzinst. Berechne das Endkapital auf Cent.`;step('Zinsen im ersten Jahr',`${k} · ${p}/100 = `,z,' €','Im ersten Jahr ist das Startkapital die Grundlage.');step('Kapital nach einem Jahr',`${k} + ${z} = `,k1,' €','Die Zinsen werden dem Kapital zugeschlagen.');step('Endkapital',`${f(k1)} · ${f(1+p/100)} = `,+((k1+z2).toFixed(2)),' €','Im zweiten Jahr wird das gesamte neue Kapital verzinst.');break;}
 case 'compound': {const red=a,total=a+b;prompt=`Ein Beutel enthält ${a} rote und ${b} blaue Kugeln. Du ziehst zweimal mit Zurücklegen. Wie wahrscheinlich ist zweimal Rot?`;step('Erster Zug','P(Rot) = ',`${red}/${total}`,'','Günstige Kugeln geteilt durch alle Kugeln.');step('Zweiter Zug','P(Rot erneut) = ',`${red}/${total}`,'','Durch Zurücklegen bleibt die Zusammensetzung unverändert.');step('Pfadwahrscheinlichkeit',`${red}/${total} · ${red}/${total} = `,`${red*red}/${total*total}`,'','Multipliziere entlang des Pfades.');break;}
 case 'binomialFormula': prompt=`Ergänze die ausmultiplizierte Form von (x + ${a})².`;step('Mittelterm-Faktor',`2 · ${a} = `,2*a,'','Der gemischte Term tritt zweimal auf.');step('Konstante',`${a}² = `,a*a,'',`Der vollständige Term ist x² + ${2*a}x + ${a*a}.`);break;
 case 'surface': prompt=`Ein Quader hat Kanten ${a}, ${b} und ${c} cm. Berechne die Oberfläche.`;step('Erstes Flächenpaar',`2 · ${a} · ${b} = `,2*a*b,' cm²','Zähle die beiden gegenüberliegenden Flächen dieses Typs.');step('Übrige Flächenpaare',`2 · (${a} · ${c} + ${b} · ${c}) = `,2*(a*c+b*c),' cm²','Es gibt noch zwei weitere Paare.');step('Gesamtoberfläche',`${2*a*b} + ${2*(a*c+b*c)} = `,2*(a*b+a*c+b*c),' cm²','Addiere alle sechs Flächen.');break;
 case 'slope': {const x1=1,x2=3,m=r(-3,4),y1=m+b,y2=3*m+b;prompt=`Bestimme die Steigung der Geraden durch A(1, ${y1}) und B(3, ${y2}).`;step('Höhenänderung',`${y2} − (${y1}) = `,2*m,'','Behalte die Reihenfolge B minus A bei.');step('Waagerechte Änderung','3 − 1 = ',2,'','Verwende dieselbe Punktreihenfolge.');step('Steigung',`${2*m} : 2 = `,m,'','Steigung ist Höhenänderung geteilt durch waagerechte Änderung.');visual={kind:'line',m,b};break;}
 case 'quadratic': {const x=-a,y=b;prompt=`Löse x² + (${a-b})x − ${a*b} = 0 mit der Faktorisierung (x + ${a})(x − ${b}) = 0.`;step('Erste Nullstelle',`x + ${a} = 0 ⇒ x = `,x,'','Setze die erste Klammer gleich null.');step('Zweite Nullstelle',`x − ${b} = 0 ⇒ x = `,y,'','Setze auch die zweite Klammer gleich null.');step('Probe der ersten Lösung',`(${x})² + (${a-b}) · (${x}) − ${a*b} = `,0,'','Eine echte Nullstelle ergibt den Funktionswert null.');break;}
 case 'powers': prompt=`Vereinfache ${c}^${a} · ${c}^${b}. Gib den neuen Exponenten und die Basis an.`;step('Neuer Exponent',`${a} + ${b} = `,a+b,'','Bei gleicher Basis addieren sich die Exponenten im Produkt.');step('Basis','Unveränderte Basis: ',c,'','Die Basis bleibt erhalten.');break;
 case 'rootRules': {const d=pick([2,3,5]);prompt=`Vereinfache √${a*a*d} in die Form k√d mit quadratfreiem d.`;step('Quadratischer Faktor','Größter Quadratzahlfaktor: ',a*a,'',`Zerlege den Radikanden in den quadratischen Faktor und den Rest: ${a*a*d} = ${a*a} · ${d}.`);step('Faktor vor der Wurzel',`√${a*a} = `,a,'','Ziehe den quadratischen Faktor aus der Wurzel.');step('Verbleibender Radikand','Unter der Wurzel bleibt ',d,'',`${a}√${d} ist die vereinfachte Darstellung.`);break;}
 case 'trig': {const k=r(1,3);prompt=`Ein rechtwinkliges Dreieck hat für α die Gegenkathete ${3*k}, Ankathete ${4*k} und Hypotenuse ${5*k}. Bestimme sin α und tan α.`;step('Sinus',`${3*k}/${5*k} = `,'3/5','','Sinus ist Gegenkathete durch Hypotenuse.');step('Tangens',`${3*k}/${4*k} = `,'3/4','','Tangens ist Gegenkathete durch Ankathete.');break;}
 case 'intercept': prompt=`Ein 3D-Modell wird gleichmäßig vergrößert. Aus einer ${a} cm langen Kante werden ${a*c} cm. Wie lang wird eine ursprünglich ${b} cm lange Kante?`;step('Maßstabsfaktor',`${a*c} : ${a} = `,c,'','Vergleiche entsprechende Kanten.');step('Neue Kantenlänge',`${b} · ${c} = `,b*c,' cm','Der gleiche Faktor gilt für alle Längen.');break;
 case 'parabola': {const d=r(-4,4),e=r(-4,4);prompt=`Bestimme den Scheitel von f(x) = ${a}(x − (${d}))² + (${e}).`;step('x-Koordinate des Scheitels','Die Klammer ist null bei x = ',d,'','Löse die Klammergleichung x − d = 0; dort verschwindet der quadratische Anteil.');step('y-Koordinate des Scheitels',`${a} · 0² + (${e}) = `,e,'','Setze die Scheitelstelle ein.');visual={kind:'parabola',a,d,e};break;}
 case 'cylinder': {const radius=r(2,5),h=r(3,9),base=+(3.14*radius*radius).toFixed(2);prompt=`Ein zylindrischer Wassertank hat Radius ${radius} m und Höhe ${h} m. Berechne das Volumen mit π ≈ 3,14.`;step('Radiusquadrat',`${radius}² = `,radius*radius,' m²','Quadriere den Radius, nicht den Durchmesser.');step('Grundfläche',`3,14 · ${radius*radius} = `,base,' m²','Die Grundfläche ist ein Kreis.');step('Volumen',`${f(base)} · ${h} = `,+(base*h).toFixed(2),' m³','Multipliziere mit der Höhe.');break;}
 case 'conditional': prompt=`Von ${a+b} Rad fahrenden Jugendlichen tragen ${a} einen Helm. Eine radfahrende Person wird zufällig gewählt. Wie wahrscheinlich trägt sie einen Helm?`;step('Bezugsmenge','Anzahl Rad fahrender Personen: ',a+b,'','Die Bedingung schränkt die Gruppe auf Radfahrende ein.');step('Günstige Fälle','Davon mit Helm: ',a,'','Zähle die Fälle mit beiden Eigenschaften.');step('Bedingte Wahrscheinlichkeit',`${a} / ${a+b} = `,`${a}/${a+b}`,'','Günstige Fälle geteilt durch die eingeschränkte Bezugsmenge.');break;
 case 'factor': prompt=`Faktorisiere ${a}x² + ${a*b}x vollständig.`;step('Gemeinsamer Zahlenfaktor','Größter gemeinsamer Zahlenfaktor: ',a,'','Beide Koeffizienten sind durch diesen Wert teilbar.');step('Konstante in der Klammer',`${a*b} : ${a} = `,b,'',`Mit dem gemeinsamen x-Faktor ergibt sich ${a}x(x + ${b}).`);break;
 case 'polynomial': prompt=`Bestimme alle Nullstellen von f(x) = x(x − ${a})(x + ${b}).`;step('Erster Faktor','x = 0 ⇒ Nullstelle: ',0,'','Ein Faktor ist x selbst.');step('Zweiter Faktor',`x − ${a} = 0 ⇒ x = `,a,'','Löse die zweite Klammergleichung.');step('Dritter Faktor',`x + ${b} = 0 ⇒ x = `,-b,'','Löse die dritte Klammergleichung.');break;
 case 'exponential': {const start=a*100,p=20,q=1.2;prompt=`Ein Onlinekurs startet mit ${start} Teilnehmenden. Die Zahl wächst pro Monat um ${p} %. Berechne die modellierte Zahl nach zwei Monaten.`;step('Wachstumsfaktor','1 + 20/100 = ',q,'','Der neue Bestand beträgt 120 % des vorherigen.');step('Nach einem Monat',`${start} · 1,2 = `,start*q,'','Multipliziere mit dem Faktor.');step('Nach zwei Monaten',`${f(start*q)} · 1,2 = `,+(start*q*q).toFixed(2),'','Der Faktor wird auf den neuen Bestand angewandt. Es handelt sich um einen Modellwert.');break;}
 case 'log': {const base=pick([2,3,5]),power=r(2,4);prompt=`Berechne log_${base}(${base**power}).`;step('Passender Exponent',`${base}^□ = ${base**power}; Exponent: `,power,'','Suche die Potenz mit passendem Ergebnis.');step('Kontrollwert',`${base}^${power} = `,base**power,'','Potenzieren prüft den Logarithmus.');break;}
 case 'trigExtended': {const deg=pick([30,45,60,90,120,270]);prompt=`Schreibe ${deg}° im Bogenmaß als k · π.`;step('Halbkreis in Grad','180° entsprechen π. Nenner des Umrechnungsbruchs: ',180,'','Eine halbe Drehung entspricht π Radiant.');step('Faktor vor π',`${deg}/180 = `,`${deg}/180`,'','Kürze den Bruch oder gib einen gleichwertigen Bruch ein.');break;}
 case 'derivative': {const variant=grade>=11?r(0,2):0;if(variant===2){const x=r(1,3),left=2*x*(x+b),right=x*x+a;prompt=`f(x) = (x² + ${a})(x + ${b}). Berechne f′(${x}) mit der Produktregel.`;step('Erstes Produkt',`2 · ${x} · (${x} + ${b}) = `,left,'','Leite den ersten Faktor ab und lasse den zweiten unverändert.');step('Zweites Produkt',`(${x}² + ${a}) · 1 = `,right,'','Lasse den ersten Faktor unverändert und leite den zweiten ab.');step('Ableitungswert',`${left} + ${right} = `,left+right,'','Addiere die beiden Produkte nach der Regel (uv)′ = u′v + uv′.');break;}if(variant===1){const power=r(2,3),x=r(1,2),inner=a*x+b;prompt=`f(x) = (${a}x + ${b})^${power}. Berechne f′(${x}) mit der Kettenregel.`;step('Innere Funktion am Punkt',`${a} · ${x} + ${b} = `,inner,'','Berechne den Wert der inneren linearen Funktion.');step('Innere Ableitung',`Ableitung von ${a}x + ${b}: `,a,'','Die Ableitung einer linearen Funktion ist ihre Steigung.');step('Ableitungswert',`${power} · ${inner}^${power-1} · ${a} = `,power*inner**(power-1)*a,'','Multipliziere die äußere Ableitung mit der inneren Ableitung.');break;}const power=r(2,4),x=r(1,3);prompt=`f(x) = ${a}x^${power}. Bestimme f′(${x}).`;step('Neuer Vorfaktor',`${a} · ${power} = `,a*power,'','Der alte Exponent wird zum Faktor.');step('Neuer Exponent',`${power} − 1 = `,power-1,'','Verringere den Exponenten um eins.');step('Ableitungswert',`${a*power} · ${x}^${power-1} = `,a*power*x**(power-1),'','Setze die Stelle erst in die Ableitung ein.');break;}
 case 'combinations': {const people=r(4,10);prompt=`Aus ${people} Personen werden zwei für ein Team ausgewählt. Wie viele Teams gibt es ohne Beachtung der Reihenfolge?`;step('Geordnete Paare',`${people} · ${people-1} = `,people*(people-1),'','Für die zweite Person gibt es eine Möglichkeit weniger.');step('Ungeordnete Teams',`${people*(people-1)} : 2 = `,people*(people-1)/2,'','Jedes Team wurde in zwei Reihenfolgen gezählt.');break;}
 case 'binomial': {const trials=pick([4,6,8]),pairs=trials*(trials-1)/2;prompt=`Eine faire Münze wird ${trials}-mal unabhängig geworfen. Berechne die Wahrscheinlichkeit für genau zweimal Kopf.`;step('Anordnungen für zwei Erfolge',`${trials} · ${trials-1} / 2 = `,pairs,'','Wähle die zwei Positionen für Kopf ohne Reihenfolge.');step('Alle Wurffolgen',`2^${trials} = `,2**trials,'','Bei einer fairen Münze sind alle Wurffolgen gleich wahrscheinlich.');step('Wahrscheinlichkeit',`${pairs}/${2**trials} = `,`${pairs}/${2**trials}`,'','Teile die günstigen durch alle Wurffolgen.');break;}
 case 'sphere': {const radius=r(1,5),cube=radius**3,top=+(4*3.14*cube).toFixed(2);prompt=`Berechne das Volumen einer Kugel mit Radius ${radius} cm. Nutze π ≈ 3,14, runde am Ende auf zwei Nachkommastellen.`;step('Radius hoch drei',`${radius}³ = `,cube,' cm³','Volumen skaliert mit der dritten Potenz des Radius.');step('Zähler der Volumenformel',`4 · 3,14 · ${cube} = `,top,' cm³','Multipliziere die Faktoren im Zähler.');step('Volumen',`${f(top)} : 3 ≈ `,+(top/3).toFixed(2),' cm³','Teile durch drei und runde erst am Ende.');break;}
 case 'change': {const x1=r(0,2),x2=r(3,6);prompt=`f(x) = x². Berechne die mittlere Änderungsrate von x = ${x1} bis x = ${x2}.`;step('Änderung der Funktionswerte',`${x2}² − ${x1}² = `,x2*x2-x1*x1,'','Berechne zuerst die Höhenänderung.');step('Änderung der x-Werte',`${x2} − ${x1} = `,x2-x1,'','Bestimme die Intervalllänge.');step('Mittlere Änderungsrate',`${x2*x2-x1*x1} : ${x2-x1} = `,x2+x1,'','Teile Höhenänderung durch Intervalllänge.');break;}
 case 'extrema': {const d=r(-4,4),e=r(-4,4);prompt=`Untersuche f(x) = (x − (${d}))² + (${e}) auf ein Minimum. Gib Stelle und Funktionswert an.`;step('Kritische Stelle',`2(x − (${d})) = 0 ⇒ x = `,d,'','Setze die erste Ableitung gleich null.');step('Zweite Ableitung','f″(x) = ',2,'','Der positive Wert bestätigt ein Minimum.');step('Minimaler Funktionswert',`f(${d}) = `,e,'','Setze die gefundene Stelle in die Ausgangsfunktion ein.');break;}
 case 'integral': {const power=r(1,3),upper=r(1,3);prompt=`Berechne das bestimmte Integral von 0 bis ${upper} über (${power+1})x^${power}.`;step('Exponent der Stammfunktion',`${power} + 1 = `,power+1,'',`Eine Stammfunktion ist F(x) = x^${power+1}.`);step('Oberer Grenzwert',`F(${upper}) = ${upper}^${power+1} = `,upper**(power+1),'','Setze die obere Grenze in die Stammfunktion ein.');step('Integral',`${upper**(power+1)} − F(0) = `,upper**(power+1),'','Ziehe den unteren Grenzwert ab, hier F(0) = 0.');break;}
 case 'vectors': {const u=[a,-b,c],v=[b,a,-a];prompt=`Addiere die Vektoren (${u.join(', ')}) und (${v.join(', ')}).`;for(let i=0;i<3;i++)step(`${'xyz'[i]}-Komponente`,`${u[i]} + (${v[i]}) = `,u[i]+v[i],'','Addiere die entsprechenden Komponenten.');break;}
 case 'dot': {const u=[a,-b,c],v=[b,a,a];prompt=`Berechne das Skalarprodukt (${u.join(', ')}) · (${v.join(', ')}).`;step('Erstes Produkt',`${a} · ${b} = `,a*b,'','Verknüpfe die ersten Komponenten.');step('Zweites Produkt',`${-b} · ${a} = `,-a*b,'','Verknüpfe die zweiten Komponenten.');step('Skalarprodukt',`${a*b} + (${-a*b}) + ${c} · ${a} = `,a*c,'','Addiere alle drei Komponentenprodukte.');break;}
 case 'lines': {const t=r(-2,3),p=[a,b,c],v=[1,-2,3];prompt=`g: X = (${p.join(', ')}) + t · (${v.join(', ')}). Bestimme den Punkt für t = ${t}.`;for(let i=0;i<3;i++)step(`${'xyz'[i]}-Koordinate`,`${p[i]} + (${t}) · (${v[i]}) = `,p[i]+t*v[i],'','Setze in allen Koordinaten denselben Parameter ein.');break;}
 case 'distance': {const k=r(1,3);prompt=`Berechne den Abstand von A(${a}, ${b}, ${c}) zu B(${a+3*k}, ${b+4*k}, ${c}).`;step('x-Differenz',`${a+3*k} − ${a} = `,3*k,'','Bilde den Verbindungsvektor B − A.');step('Summe der Differenzquadrate',`${3*k}² + ${4*k}² + 0² = `,25*k*k,'','Nutze den räumlichen Pythagoras.');step('Abstand',`√${25*k*k} = `,5*k,'','Der Abstand ist die nichtnegative Länge.');break;}
 case 'matrices': prompt=`Multipliziere die Matrix [${a}, ${b}; ${c}, ${a}] mit dem Spaltenvektor (${b}, ${c}).`;step('Erstes Teilprodukt',`${a} · ${b} = `,a*b,'','Beginne mit dem ersten Eintrag der ersten Zeile.');step('Erste Ergebniskomponente',`${a*b} + ${b} · ${c} = `,a*b+b*c,'','Verknüpfe die gesamte erste Zeile mit dem Vektor.');step('Zweite Ergebniskomponente',`${c} · ${b} + ${a} · ${c} = `,c*b+a*c,'','Verknüpfe dann die zweite Zeile.');break;
 case 'hypothesis': {const type=r(1,2),context=pick(['zur Wasserqualität','zur Produktionsqualität','zur Wirkung einer Lernmethode']);prompt=`Ein Test ${context} ${type===1?'verwirft eine tatsächlich wahre':'verwirft eine tatsächlich falsche nicht'} Nullhypothese. Ordne die Entscheidung ein.`;step('Wahrheit von H₀','Ist H₀ tatsächlich wahr? (ja/nein): ',type===1?'ja':'nein','','Unterscheide die tatsächliche Situation von der Testentscheidung.');step('Entscheidung','Wird H₀ verworfen? (ja/nein): ',type===1?'ja':'nein','','Lies die Testentscheidung unabhängig vom Wahrheitsstatus.');step('Fehlerart','Fehler welcher Art (1 oder 2)? ',type,'','Wahre H₀ verwerfen: 1. Art. Falsche H₀ nicht verwerfen: 2. Art.');break;}
 default: throw new Error(`Fehlende Lerneinheit: ${topic.id}`);
 }
 return {prompt,steps,visual,topicId:topic.id,grade,signature:JSON.stringify([topic.id,prompt])};
}
export const learningStages = [
 {id:'warmup',title:'Einfach starten',short:'Warm-up',description:'Eine leichte Aufgabe. Du ergänzt nur das Ergebnis.'},
 {id:'one',title:'Eine Lücke',short:'Eine Lücke',description:'Der Rechenweg steht da. Ein zufällig gewählter Schritt fehlt.'},
 {id:'many',title:'Mehr Lücken',short:'Mehr Lücken',description:'Übernimm mehr: Jetzt ergänzt du mehrere Schritte.'},
 {id:'solo',title:'Ganz allein lösen',short:'Selbst lösen',description:'Keine vorgegebenen Rechnungen. Entwickle den Weg und löse alle Teilschritte selbst.'}
];
export function gapIndices(task,stage,rng=Math.random){
 const all=task.steps.map((_,i)=>i);
 if(stage==='warmup')return [all.at(-1)];
 if(stage==='one')return [rand(0,all.length-1,rng)];
 if(stage==='many')return shuffle(all,rng).slice(0,Math.max(2,all.length-1)).sort((a,b)=>a-b);
 return all;
}
export function checkLearning(task,indices,answers){return indices.map(i=>isCorrect({answer:task.steps[i].value},answers[i]));}
